// ---------------------------------------------------------------- black box
// The last steps the firmware went through are kept in RTC memory, which
// survives a watchdog or crash reset (not a power cut). After a reset they
// are sent to the bridge in a "reset_report" frame and written to its log.
enum Crumb : uint8_t {
  CR_NONE = 0,
  CR_BOOT,
  CR_IDLE,
  CR_STATS,
  CR_CONFIG,
  CR_WEATHER,
  CR_DISKS,
  CR_CLAUDE,
  CR_PING,
  CR_BAD_JSON,
  CR_TOUCH,
  CR_TAB,
  CR_RENDER,
  CR_RENDER_DONE,
  CR_FOOTER,
  CR_TAB_ICON,
  CR_FOOTER_DONE,
  CR_BUTTON,
  CR_BUTTON_DONE,
  CR_FLASH,
  CR_SEND_MACRO,
  CR_WAKE,
  CR_SLEEP,
  CR_HEADER,
  CR_MONITOR_DYN,
  CR_DISK_ROWS,
  CR_HOLD,
  CR_POWER_UI,
  CR_SEND_POWER,
  CR_MEDIA,
  CR_SEND_MEDIA,
  CR_MUSIC_FX,
  CR_COUNT
};

