// Footer tabs: a full-colour icon per page (src/tab_icons.h). The selected
// tab has a purple background with a magenta border.
constexpr int TAB_H = 28;
constexpr uint16_t C_TAB_SELECTED = 0x50EF;         // RGB(80, 30, 120)
constexpr uint16_t C_TAB_SELECTED_BORDER = 0xCA9F;  // RGB(200, 80, 255)

// Fallback text if an icon is missing.
const char *const TAB_LABELS[TAB_COUNT] = {"MONITOR", "STORAGE", "WEATHER",
                                           "DECK", "MUSIC"};

uint16_t blend565(uint16_t under, uint16_t over, uint8_t alpha) {
  const uint32_t a = alpha;
  const uint32_t ia = 255 - a;
  const uint32_t r = (((over >> 11) & 0x1F) * a + ((under >> 11) & 0x1F) * ia + 127) / 255;
  const uint32_t g = (((over >> 5) & 0x3F) * a + ((under >> 5) & 0x3F) * ia + 127) / 255;
  const uint32_t b = ((over & 0x1F) * a + (under & 0x1F) * ia + 127) / 255;
  return static_cast<uint16_t>((r << 11) | (g << 5) | b);
}

void drawTabIcon(const TabIcon &icon, int cx, int cy, uint16_t bg) {
  static uint16_t pixels[TAB_ICON_BOX * TAB_ICON_BOX];
  const int count = icon.width * icon.height;
  for (int i = 0; i < count; ++i) {
    const uint8_t *p = icon.data + i * 3;
    const uint8_t alpha = pgm_read_byte(p);
    const uint16_t color = (pgm_read_byte(p + 1) << 8) | pgm_read_byte(p + 2);
    pixels[i] = alpha == 0 ? bg : alpha == 255 ? color : blend565(bg, color, alpha);
  }
  const bool swap = tft.getSwapBytes();
  tft.setSwapBytes(true);  // pixels[] holds normal 16-bit colours
  tft.pushImage(cx - icon.width / 2, cy - icon.height / 2, icon.width,
                icon.height, pixels);
  tft.setSwapBytes(swap);
}

void drawTab(int index, bool selected) {
  const int x = index * TAB_W;
  const uint16_t bg = selected ? C_TAB_SELECTED : C_PANEL;
  if (selected) {
    tft.fillRect(x + 1, FOOTER_Y, TAB_W - 2, TAB_H, bg);
    tft.drawRect(x + 1, FOOTER_Y, TAB_W - 2, TAB_H, C_TAB_SELECTED_BORDER);
  }
  if (index < static_cast<int>(TAB_ICON_COUNT)) {
    drawTabIcon(TAB_ICONS[index], x + TAB_W / 2, FOOTER_Y + TAB_H / 2, bg);
  } else {
    tft.setTextDatum(MC_DATUM);
    tft.setTextColor(C_TEXT, bg);
    const uint8_t font = tft.textWidth(TAB_LABELS[index], 2) > TAB_W - 6 ? 1 : 2;
    tft.drawString(TAB_LABELS[index], x + TAB_W / 2, FOOTER_Y + TAB_H / 2, font);
  }
}

void drawFooter(Page selected) {
  const int sel = static_cast<int>(selected);
  crumb(CR_FOOTER, sel);
  tft.fillRect(0, FOOTER_Y, SCREEN_W, TAB_H, C_PANEL);
  for (int i = 0; i < TAB_COUNT; ++i) {
    crumb(CR_TAB_ICON, i);
    drawTab(i, sel == i);
    // Divider between tabs, left out next to the selected tab.
    if (i > 0 && sel != i && sel != i - 1) {
      tft.drawFastVLine(i * TAB_W, FOOTER_Y + 5, 18, C_BAR_BG);
    }
  }
  crumb(CR_FOOTER_DONE, sel);
}

// ------------------------------------------------------------------- disks
uint8_t diskPageCount() {
  if (diskCount == 0) return 1;
  return (diskCount + DISKS_PER_PAGE - 1) / DISKS_PER_PAGE;
}

String sizeText(float usedGB, float totalGB) {
  if (isnan(usedGB) || isnan(totalGB)) return "--";
  if (totalGB >= 1000.0f) {
    return String(usedGB / 1024.0f, 1) + "/" + String(totalGB / 1024.0f, 1) + "T";
  }
  return String(usedGB, 0) + "/" + String(totalGB, 0) + "G";
}

String rateText(float value) {
  if (isnan(value)) return "--";
  return String(value, value >= 100.0f ? 0 : 1);
}

// Two lines per drive: name/label/usage bar/size, then read/write speed.
// Only the value areas are cleared, so periodic updates do not flicker.
void drawDiskRow(const DiskEntry &disk, int y) {
  constexpr int barX = 98;
  constexpr int barW = 104;
  constexpr int barH = 10;
  const int line1 = y + 9;
  const int line2 = y + 25;

  tft.setTextDatum(ML_DATUM);
  tft.setTextColor(C_TEXT, C_BG);
  tft.drawString(disk.name, 8, line1, 2);
  tft.setTextColor(C_MUTED, C_BG);
  tft.drawString(disk.label, 34, line1, 1);

  tft.fillRoundRect(barX, y + 4, barW, barH, 3, C_BAR_BG);
  const int fillW = static_cast<int>((barW - 2) * clampPct(disk.used) / 100.0f);
  if (fillW > 0) {
    tft.fillRoundRect(barX + 1, y + 5, fillW, barH - 2, 2, usageColor(disk.used));
  }

  tft.fillRect(204, y, SCREEN_W - 204, 18, C_BG);
  tft.setTextDatum(MR_DATUM);
  tft.setTextColor(usageColor(disk.used), C_BG);
  tft.drawString(fmtValue(disk.used) + "%", 246, line1, 2);
  tft.setTextColor(C_MUTED, C_BG);
  tft.drawString(sizeText(disk.usedGB, disk.totalGB), 314, line1, 1);

  // Read / write line.
  tft.fillRect(30, y + 19, SCREEN_W - 30, 12, C_BG);
  const bool known = !isnan(disk.readMBs) || !isnan(disk.writeMBs);
  const float activity = (isnan(disk.readMBs) ? 0.0f : disk.readMBs) +
                         (isnan(disk.writeMBs) ? 0.0f : disk.writeMBs);
  tft.setTextDatum(ML_DATUM);
  tft.setTextColor(activity >= 1.0f ? C_ACCENT : C_MUTED, C_BG);
  if (known) {
    tft.drawString("R " + rateText(disk.readMBs) + "  W " +
                       rateText(disk.writeMBs) + " MB/s",
                   34, line2, 1);
  } else {
    tft.drawString("R/W N/A", 34, line2, 1);
  }
  tft.drawFastHLine(8, y + DISK_ROW_H - 2, SCREEN_W - 16, C_PANEL);
}

