// Shortens text until it fits in maxWidth pixels.
String fitText(const String &text, uint8_t font, int maxWidth) {
  String out = text;
  while (out.length() > 1 && tft.textWidth(out, font) > maxWidth) {
    out.remove(out.length() - 1);
  }
  return out;
}

// Program with the highest CPU use (line 1) and with the most RAM (line 2).
void drawTopProcessDynamic(int x, int y, int w, int h) {
  tft.fillRect(x + 5, y + 20, w - 10, h - 25, C_PANEL_2);
  const int maxW = w - 12;

  tft.setTextDatum(TL_DATUM);
  if (stats.topCpuName.length() == 0) {
    tft.setTextColor(C_MUTED, C_PANEL_2);
    tft.drawString("--", x + 6, y + 22, 2);
    return;
  }

  const String cpuValue = " " + fmtValue(stats.topCpu, 0) + "%";
  const int cpuValueW = tft.textWidth(cpuValue, 2);
  const String cpuName = fitText(stats.topCpuName, 2, maxW - cpuValueW);
  tft.setTextColor(C_TEXT, C_PANEL_2);
  tft.drawString(cpuName, x + 6, y + 22, 2);
  tft.setTextColor(usageColor(stats.topCpu), C_PANEL_2);
  tft.drawString(cpuValue, x + 6 + tft.textWidth(cpuName, 2), y + 22, 2);

  String ramValue = "--";
  if (!isnan(stats.topRamGB)) {
    ramValue = stats.topRamGB >= 1.0f ? String(stats.topRamGB, 1) + "G"
                                      : String(stats.topRamGB * 1024.0f, 0) + "M";
  }
  const String ramPrefix = "RAM ";
  const String ramSuffix = " " + ramValue;
  const String ramName =
      fitText(stats.topRamName, 1,
              maxW - tft.textWidth(ramPrefix, 1) - tft.textWidth(ramSuffix, 1));
  tft.setTextColor(C_MUTED, C_PANEL_2);
  tft.drawString(ramPrefix + ramName + ramSuffix, x + 6, y + 43, 1);
}

// Claude plan usage: 5-hour session (line 1) and weekly limit (line 2).
void drawClaudeDynamic(int x, int y, int w, int h) {
  tft.fillRect(x + 5, y + 20, w - 10, h - 25, C_PANEL_2);
  tft.setTextDatum(TL_DATUM);

  if (claude.state != "ok") {
    String line1 = "--";
    String line2 = "";
    uint16_t color = C_MUTED;
    if (claude.state == "login") {
      line1 = "LOGIN";
      line2 = "run claude";
      color = C_WARN;
    } else if (claude.state == "nologin") {
      line1 = "NO LOGIN";
      line2 = "Claude Code";
      color = C_WARN;
    } else if (claude.state == "error") {
      line2 = "no data";
    }
    tft.setTextColor(color, C_PANEL_2);
    tft.drawString(line1, x + 6, y + 22, 2);
    tft.setTextColor(C_MUTED, C_PANEL_2);
    tft.drawString(line2, x + 6, y + 43, 1);
    return;
  }

  tft.setTextColor(usageColor(claude.session), C_PANEL_2);
  const String session = "5H " + fmtValue(claude.session) + "%";
  tft.drawString(session, x + 6, y + 22, 2);
  const bool resetFits = tft.textWidth(session, 2) + 4 +
                             tft.textWidth(claude.sessionReset, 1) <=
                         w - 12;
  if (claude.sessionReset.length() && resetFits) {
    tft.setTextDatum(TR_DATUM);
    tft.setTextColor(C_MUTED, C_PANEL_2);
    tft.drawString(claude.sessionReset, x + w - 6, y + 26, 1);
    tft.setTextDatum(TL_DATUM);
  }

  tft.setTextColor(usageColor(claude.weekly), C_PANEL_2);
  const String weekly = "7D " + fmtValue(claude.weekly) + "%";
  tft.drawString(weekly, x + 6, y + 43, 1);
  if (claude.weeklyReset.length()) {
    tft.setTextDatum(TR_DATUM);
    tft.setTextColor(C_MUTED, C_PANEL_2);
    tft.drawString(claude.weeklyReset, x + w - 6, y + 43, 1);
    tft.setTextDatum(TL_DATUM);
  }
}

